import itertools
n=14
S={1,13,3,11,7}
edges=[]
for i in range(n):
    for j in range(i+1,n):
        if (j-i)%n in S:
            edges.append((i,j))
print(len(edges), edges)
# degrees
deg=[0]*n
for u,v in edges:
    deg[u]+=1;deg[v]+=1
print(deg)
# clique num
maxcl=0; maxcliques=[]
for r in range(1,n+1):
    found=False
    for comb in itertools.combinations(range(n),r):
        if all(((j-i)%n in S) for i,j in itertools.combinations(comb,2)):
            found=True; maxcl=r; maxcliques.append(comb)
    if not found and r>maxcl: break
print('clique', maxcl, maxcliques[-10:])
# chromatic number brute find <=5
def colorable(k):
    colors=[-1]*n
    order=sorted(range(n), key=lambda x:-deg[x])
    adj=[set() for _ in range(n)]
    for u,v in edges: adj[u].add(v); adj[v].add(u)
    def bt(idx):
        if idx==n: return True
        v=order[idx]
        used={colors[w] for w in adj[v] if colors[w]!=-1}
        for c in range(k):
            if c not in used:
                colors[v]=c
                if bt(idx+1): return True
                colors[v]=-1
        return False
    res=bt(0)
    return res, colors
for k in range(1,6):
    res, col = colorable(k)
    print(k,res,col if res else '')
